INSERT INTO corr (ref, ancien, chapitre, enonce, choix, bonne, complement) VALUES
('Q0000', 'L''orthographe officielle du créole haïtien fut établie en :', NULL, 'En quelle année l''orthographe officielle du créole haïtien fut-elle établie ?', '["En 1979", "En 1804", "En 1961", "En 2000"]', 'En 1979', 'Elle a été fixée par décret, puis confortée par la Constitution de 1987.'),
('Q0001', 'En créole haïtien, le mot "manje" signifie :', NULL, 'Que signifie le mot créole « manje » ?', '["Manger ou nourriture", "Maison ou foyer", "Enfant ou bébé", "Partir ou sortir"]', 'Manger ou nourriture', 'Le sens (verbe ou nom) dépend du contexte.'),
('Q0003', 'En créole haïtien, le "ou" représente :', NULL, 'Quel son représente la graphie « ou » en créole haïtien ?', '["Le son [u] de « nous »", "Le son « o »", "Le son « eu »", "Le son « i »"]', 'Le son [u] de « nous »', NULL),
('Q0004', 'La marque du pluriel en créole haïtien est :', NULL, 'Comment marque-t-on le pluriel en créole haïtien ?', '["Avec « yo » après le nom", "Avec un « s » final", "En changeant la voyelle", "Avec un article devant"]', 'Avec « yo » après le nom', 'Exemple : timoun yo = les enfants.'),
('Q0006', 'Le pronom "li" en créole haïtien correspond à :', NULL, 'À quel pronom français correspond « li » en créole ?', '["Il ou elle", "Il seulement", "Elle seulement", "Ils ou elles"]', 'Il ou elle', 'Le créole ne distingue pas le genre.'),
('Q0007', 'La négation en créole haïtien s''exprime avec :', NULL, 'Comment exprime-t-on la négation en créole haïtien ?', '["Avec « pa » avant le verbe", "Avec « ne… pas »", "Avec « non » devant le verbe", "Avec « pa… non »"]', 'Avec « pa » avant le verbe', 'Exemple : Mwen pa konnen = Je ne sais pas.'),
('Q0008', 'Le temps futur en créole haïtien est indiqué par :', NULL, 'Quelle particule marque le futur en créole haïtien ?', '["Pral", "Te", "Konn", "Fin"]', 'Pral', 'On utilise aussi ap ou va ; la particule se place avant le verbe.'),
('Q0009', 'En créole haïtien, les verbes :', NULL, 'Comment les verbes créoles varient-ils selon la personne ?', '["Ils sont invariables", "Comme en français", "Selon le sujet", "Selon le genre"]', 'Ils sont invariables', 'Les particules (te, ap, pral) indiquent le temps.'),
('Q0010', 'Le passé en créole haïtien est indiqué par :', NULL, 'Quelle particule marque le passé en créole haïtien ?', '["Te", "Pral", "Ap", "Ta"]', 'Te', 'Exemple : Mwen te manje = J''ai mangé / Je mangeais.'),
('Q0012', 'L''article défini "le/la/les" en créole haïtien est exprimé par :', NULL, 'Où se place l''article défini en créole haïtien ?', '["Après le nom", "Avant le nom", "Il n''existe pas", "En fin de phrase"]', 'Après le nom', 'Formes : a, an, la, lan, nan, selon la fin du mot.'),
('Q0013', 'Le terme "griot" dans la culture haïtienne désigne :', NULL, 'Que désigne le mot « griyo » dans la cuisine haïtienne ?', '["Du porc frit", "Un ragoût de poulet", "Un plat de poisson", "Une soupe de légumes"]', 'Du porc frit', 'C''est un plat traditionnel.'),
('Q0014', 'La structure d''une phrase simple en créole haïtien est :', NULL, 'Quel est l''ordre des mots dans une phrase simple en créole ?', '["Sujet, verbe, objet", "Verbe, sujet, objet", "Objet, verbe, sujet", "Verbe, objet, sujet"]', 'Sujet, verbe, objet', 'Les marqueurs de temps se placent entre le sujet et le verbe.'),
('Q0015', 'En créole haïtien, "nan" peut être :', NULL, 'Quelles fonctions le mot « nan » peut-il avoir en créole ?', '["Article, préposition ou démonstratif", "Article seulement", "Préposition seulement", "Verbe"]', 'Article, préposition ou démonstratif', 'Le sens dépend du contexte.'),
('Q0016', 'Le créole haïtien est une langue :', NULL, 'Quelle est la base lexicale principale du créole haïtien ?', '["Le français", "L''espagnol", "L''anglais", "Les langues africaines seules"]', 'Le français', 'Il a aussi des apports africains, espagnols, anglais, taïnos et portugais.'),
('Q0017', 'Le mot créole "lakou" désigne :', NULL, 'Que désigne le mot créole « lakou » ?', '["La cour commune familiale", "Une école", "Un marché", "Une rivière"]', 'La cour commune familiale', 'Unité sociale et familiale traditionnelle regroupant plusieurs maisons.'),
('Q0019', 'Le créole haïtien a été officiellement reconnu comme langue nationale en :', NULL, 'Depuis quelle Constitution le créole est-il langue officielle d''Haïti ?', '["Celle de 1987", "Celle de 1804", "Celle de 1950", "Celle de 2012"]', 'Celle de 1987', 'Avec le français. La Constitution de 1983 le reconnaissait déjà comme langue nationale.'),
('Q0020', 'Le mot "degaje" en créole haïtien signifie :', NULL, 'Que signifie le mot créole « degaje » ?', '["Se débrouiller", "Partir", "Étudier", "Manger"]', 'Se débrouiller', 'Trouver des solutions malgré les difficultés.'),
('Q0021', 'La littérature en créole haïtien comprend notamment :', NULL, 'Quel roman de Frankétienne (1975) est le premier roman écrit en créole ?', '["Dezafi", "Gouverneurs de la rosée", "Les Arbres musiciens", "Amour, colère et folie"]', 'Dezafi', 'Georges Castera est aussi un grand auteur en créole.'),
('Q0022', 'Le proverbe créole "Piti piti zwazo fè nich li" signifie :', NULL, 'Que signifie le proverbe « Piti piti zwazo fè nich li » ?', '["La patience mène au succès", "Il faut voler pour réussir", "Les oiseaux sont libres", "L''union fait la force"]', 'La patience mène au succès', '« Petit à petit, l''oiseau fait son nid ».'),
('Q0024', 'En créole haïtien, l''interrogation directe se forme :', NULL, 'Comment forme-t-on une question directe en créole haïtien ?', '["Avec un mot interrogatif ou l''intonation", "En inversant sujet et verbe", "En ajoutant « -ou » à la fin", "En changeant le temps"]', 'Avec un mot interrogatif ou l''intonation', 'Mots interrogatifs : ki, kijan, poukisa, èske.'),
('Q0025', 'La devinette créole "Devinèt, devinèt?" commence une conversation ludique. La réponse d''invitation est :', NULL, 'Quelle formule ouvre traditionnellement une devinette créole ?', '["« Tim tim ? »", "« Krik ? »", "« Onè ? »", "« Sak pase ? »"]', '« Tim tim ? »', 'L''auditoire répond « Bwa chèch ! ».'),
('Q0026', 'Un discours formel en créole haïtien commence généralement par :', NULL, 'Par quelles salutations commence traditionnellement une prise de parole formelle en créole ?', '["« Onè ! » « Respè ! »", "Un cri de ralliement", "« Mesye dam » seulement", "« Sak pase ? »"]', '« Onè ! » « Respè ! »', 'On salue tous les groupes présents.'),
('Q0027', 'L''expression "Anmwe!" en créole haïtien est :', NULL, 'Qu''est-ce que l''expression « Anmwe ! » en créole ?', '["Un appel au secours", "Une célébration", "Un juron", "Une bonne surprise"]', 'Un appel au secours', NULL),
('Q0032', 'Le mot "rezo" en créole haïtien peut désigner :', NULL, 'Que désigne le mot créole « rezo » ?', '["Un réseau", "Un poisson", "Une réunion", "Un repas"]', 'Un réseau', 'Réseau internet ou social.'),
('Q0033', 'Le proverbe "Bouch granmoun santi, men pawòl li bon" enseigne :', NULL, 'Qu''enseigne le proverbe « Bouch granmoun santi, men pawòl li bon » ?', '["Respecter la sagesse des anciens", "Les anciens ont toujours tort", "Se méfier des conseils", "La forme prime sur le fond"]', 'Respecter la sagesse des anciens', 'Même si la forme déplaît, leurs paroles sont précieuses.'),
('Q0034', 'La radio en Haïti joue un rôle particulièrement important car :', NULL, 'Pourquoi la radio joue-t-elle un rôle si important en Haïti ?', '["Elle touche presque toute la population", "C''est le seul média autorisé", "Elle diffuse en français seulement", "L''État seul la contrôle"]', 'Elle touche presque toute la population', 'Y compris les personnes qui ne lisent pas et les zones sans électricité stable.'),
('Q0036', 'Un paragraphe bien structuré en créole (comme en français) doit avoir :', NULL, 'Que doit contenir un paragraphe bien structuré ?', '["Idée principale, appuis, conclusion", "Des phrases courtes seulement", "Des répétitions", "Un vocabulaire simple seulement"]', 'Idée principale, appuis, conclusion', 'L''idée principale est soutenue par des arguments ou exemples.'),
('Q0039', 'La créolisation est un processus par lequel :', NULL, 'Qu''est-ce que la créolisation ?', '["La naissance d''une langue par contact", "La simplification du français", "L''apprentissage du français", "La disparition d''une langue"]', 'La naissance d''une langue par contact', 'Des langues en contact donnent une nouvelle langue avec sa propre grammaire.'),
('Q0041', 'Dans un résumé de texte en créole, il faut :', 'Communication orale et écrite en créole', 'Que faut-il faire dans un résumé de texte en créole ?', '["Reprendre l''essentiel avec ses mots", "Copier le texte", "Donner son opinion", "Écrire un poème"]', 'Reprendre l''essentiel avec ses mots', 'Sans détails et sans changer le sens.'),
('Q0042', 'Comment rédige-t-on correctement une lettre formelle en créole ?', NULL, 'Par quoi commence une lettre formelle en créole ?', '["Le lieu et la date", "Directement le contenu", "Une phrase en français", "« Alo, »"]', 'Le lieu et la date', 'Puis la salutation (« Chè Mesye / Madam »), le corps, la formule de politesse et la signature.'),
('Q0043', 'Le mot "vèvè" dans la culture haïtienne désigne :', NULL, 'Que désigne le mot « vèvè » dans la culture haïtienne ?', '["Un dessin sacré d''un lwa", "Un tissu", "Un instrument", "Une danse"]', 'Un dessin sacré d''un lwa', 'Il est associé au vodou.'),
('Q0044', 'Le mot créole "lakay" signifie :', NULL, 'Que signifie le mot créole « lakay » ?', '["Chez soi, la maison", "Une école", "Un marché", "Un village"]', 'Chez soi, la maison', 'Au sens figuré : la patrie.'),
('Q0045', 'La langue créole haïtienne a environ combien de locuteurs dans le monde ?', NULL, 'Combien de locuteurs compte environ le créole haïtien ?', '["Environ 12 millions", "Environ 1 million", "Environ 50 millions", "Environ 100 000"]', 'Environ 12 millions', 'En Haïti et dans la diaspora.'),
('Q0047', 'L''expression "pa pran tèt" en créole haïtien signifie :', NULL, 'Que signifie l''expression créole « pa pran tèt » ?', '["Ne pas s''inquiéter", "Réfléchir sérieusement", "Apprendre par cœur", "Être attentif"]', 'Ne pas s''inquiéter', NULL),
('Q0048', 'Pour exprimer une condition en créole haïtien, on utilise :', NULL, 'Quel mot introduit une condition en créole haïtien ?', '["Si", "Lè", "Pou", "Ak"]', 'Si', 'Exemple : Si ou te la, mwen ta kontan.'),
('Q0049', 'En créole haïtien, pour rapporter les paroles de quelqu''un (discours direct), on utilise :', NULL, 'Comment introduit-on le discours direct en créole ?', '["Avec « Li di : »", "Avec « Li panse »", "Avec le subjonctif", "On ne l''utilise pas"]', 'Avec « Li di : »', 'Les paroles suivent entre guillemets ou après un tiret.'),
('Q0050', 'Pour écrire une lettre formelle en créole haïtien, on commence généralement par :', NULL, 'Quelle formule d''appel convient à une lettre formelle en créole ?', '["« Chè Msye… »", "« Sak pase ! »", "Le prénom seul", "Aucune formule"]', '« Chè Msye… »', 'Ou « Respektab… » selon le destinataire.'),
('Q0051', 'Dans un texte narratif en créole, les temps principaux utilisés sont :', NULL, 'Quel marqueur exprime une habitude passée dans un récit en créole ?', '["Te konn", "Pral", "Ap", "Ta"]', 'Te konn', '« Te + verbe » sert aux actions ponctuelles du passé.'),
('Q0052', 'La ponctuation en créole écrit officiel :', NULL, 'Quelles règles de ponctuation suit le créole écrit officiel ?', '["Celles du français", "Il n''y en a pas", "Des règles toutes différentes", "Le point et la virgule seuls"]', 'Celles du français', NULL),
('Q0053', 'Pour exprimer son opinion dans un texte argumentatif en créole, on peut utiliser :', NULL, 'Quelle expression permet d''exprimer son opinion en créole ?', '["« Dapre mwen… »", "« Sak pase… »", "« Krik… »", "« Anmwe… »"]', '« Dapre mwen… »', 'Aussi « Mwen panse… ».'),
('Q0054', 'Le connecteur créole "se poutèt sa" signifie :', NULL, 'Que signifie le connecteur créole « se poutèt sa » ?', '["C''est pourquoi", "Mais", "Cependant", "En plus"]', 'C''est pourquoi', 'Il introduit une conséquence.'),
('Q0055', 'Dans une description en créole, les adjectifs se placent :', NULL, 'Où se placent généralement les adjectifs en créole ?', '["Après le nom", "Avant le nom", "Loin du nom", "En fin de phrase"]', 'Après le nom', 'Exemple : chemiz blan (chemise blanche).'),
('Q0056', 'L''expression "an reyalite" dans un texte argumentatif en créole introduit :', NULL, 'Qu''introduit l''expression « an reyalite » dans un texte argumentatif ?', '["Un fait qui nuance", "Une hypothèse", "Une conclusion", "Un exemple personnel"]', 'Un fait qui nuance', NULL),
('Q0057', 'Pour écrire un dialogue en créole, on utilise :', NULL, 'Comment marque-t-on les répliques d''un dialogue en créole ?', '["Avec tirets ou guillemets", "Avec le tiret seul", "Sans marque", "Avec des parenthèses"]', 'Avec tirets ou guillemets', NULL),
('Q0058', 'Dans un résumé de texte en créole, il faut :', 'Production écrite et orale en créole', 'Comment faire un bon résumé de texte en créole ?', '["Reformuler l''essentiel", "Copier les phrases clés", "Ajouter son opinion", "Garder l''introduction seule"]', 'Reformuler l''essentiel', 'Avec ses propres mots, en respectant le sens.'),
('Q0059', 'La structure d''un exposé oral en créole comporte :', NULL, 'Quelles sont les parties d''un exposé oral en créole ?', '["Introduction, développement, conclusion", "La partie centrale seule", "Aucun ordre", "Une simple liste"]', 'Introduction, développement, conclusion', 'Prezantasyon, eksplikasyon, konklizyon.'),
('Q0060', 'Pour exprimer une cause en créole haïtien, on utilise notamment :', NULL, 'Quel connecteur créole exprime la cause ?', '["Paske", "Donk", "Men", "Pou"]', 'Paske', 'Aussi piske (puisque) et akòz (à cause de).'),
('Q0061', 'Une "redaksyon" (rédaction) en créole est évaluée principalement sur :', NULL, 'Sur quoi une rédaction en créole est-elle surtout évaluée ?', '["Contenu, cohérence, structure, orthographe", "L''originalité seule", "La longueur seule", "Les mots difficiles"]', 'Contenu, cohérence, structure, orthographe', NULL),
('Q0062', 'Le mot "men" en créole peut exprimer :', NULL, 'Quels sens peut avoir le mot « men » en créole ?', '["« Mais » ou « voici »", "« La main » seulement", "« Mais » en début seulement", "Une salutation"]', '« Mais » ou « voici »', 'Selon le contexte ; il peut aussi désigner la main.'),
('Q0063', 'Le genre en créole haïtien (masculin/féminin) :', NULL, 'Le créole haïtien a-t-il un genre grammatical ?', '["Non, il n''y a pas d''accord", "Oui, comme le français", "Seulement pour les animaux", "Oui, par des suffixes"]', 'Non, il n''y a pas d''accord', NULL),
('Q0064', 'Pour exprimer un souhait ou un désir en créole haïtien, on utilise :', NULL, 'Quelle expression traduit un souhait en créole ?', '["« Ta renmen »", "« Dwe »", "« Ka »", "« Pral »"]', '« Ta renmen »', 'Aussi « ta vle », « swete », « espere ».'),
('Q0065', 'La lecture à haute voix en créole demande de respecter :', NULL, 'Que faut-il respecter dans une lecture à haute voix en créole ?', '["Intonation, pauses, prononciation", "La vitesse seule", "L''intonation française", "Aucune règle"]', 'Intonation, pauses, prononciation', 'Les pauses suivent la ponctuation.'),
('Q0066', 'Un "pwezi" (poème) en créole se caractérise souvent par :', NULL, 'Qu''est-ce qui caractérise souvent un poème (pwezi) en créole ?', '["Images, répétitions et rimes", "L''absence de figures", "Des rimes obligatoires", "La prose seule"]', 'Images, répétitions et rimes', 'Comparaisons et métaphores (konparezon, metafò).'),
('Q0067', 'Pour donner des instructions ou des consignes en créole, on utilise souvent :', NULL, 'Quel mode utilise-t-on pour donner des consignes en créole ?', '["L''impératif", "Le passé composé", "Le conditionnel", "L''interrogatif"]', 'L''impératif', 'Exemples : Fè… (Fais…), Ale… (Va…).'),
('Q0068', 'Un texte bien "kohèran" (cohérent) en créole signifie que :', NULL, 'Que signifie qu''un texte créole est cohérent (kohèran) ?', '["Ses idées s''enchaînent logiquement", "Il est long", "Il n''a aucune répétition", "Il a des mots difficiles"]', 'Ses idées s''enchaînent logiquement', 'Pronoms et connecteurs renvoient clairement aux bons éléments.'),
('Q0069', 'Le pluriel en créole haïtien se forme avec :', NULL, 'Comment dit-on « les chats » en créole haïtien ?', '["Chat yo", "Chats", "Yo chat", "Chat chat"]', 'Chat yo', '« Yo » après le nom marque le pluriel défini.'),
('Q0070', 'Pour exprimer une opposition en créole, les connecteurs utilisés sont :', NULL, 'Quel connecteur créole exprime l''opposition ?', '["Poutan", "Paske", "Donk", "Epitou"]', 'Poutan', 'Aussi men, sepandan, okontrè.'),
('Q0071', 'La communication non-verbale dans une présentation orale en créole inclut :', NULL, 'Qu''inclut la communication non verbale dans un exposé ?', '["Regard, gestes, posture, voix", "Les mots seuls", "La vitesse seule", "Le tableau seul"]', 'Regard, gestes, posture, voix', NULL),
('Q0072', 'En créole, pour exprimer une comparaison d''égalité, on utilise :', NULL, 'Quel mot créole exprime une comparaison d''égalité ?', '["Tankou", "Pi… pase", "Mwens… pase", "Twò"]', 'Tankou', 'Exemple : Li gwo tankou yon elefan.'),
('Q0073', 'La formule traditionnelle qui ouvre un conte (kont) en créole haïtien est :', NULL, 'Quelle formule ouvre traditionnellement un conte créole ?', '["« Krik ! »", "« Il était une fois »", "« Bonjou ! »", "« Men istwa a »"]', '« Krik ! »', 'L''auditoire répond « Krak ! ».'),
('Q0074', 'Le proverbe créole "Chak jou gen travay pa l, chak jou gen pwoblèm pa l" enseigne :', NULL, 'Qu''enseigne le proverbe « Chak jou gen travay pa l, chak jou gen pwoblèm pa l » ?', '["Vivre chaque jour sans s''inquiéter", "Tout planifier", "Les problèmes durent toujours", "Éviter le travail"]', 'Vivre chaque jour sans s''inquiéter', 'Chaque jour a sa peine.'),
('Q0075', 'Morisseau-Leroy (1912-1998) est célèbre pour avoir :', NULL, 'Pour quoi Félix Morisseau-Leroy est-il célèbre ?', '["Sa traduction d''Antigone en créole", "Ses romans en français", "Ses chansons de konpa", "Sa peinture naïve"]', 'Sa traduction d''Antigone en créole', 'Antigòn montre que le créole peut porter la grande littérature.'),
('Q0076', 'Le proverbe haïtien "Deye mon gen mon" signifie :', NULL, 'Que signifie le proverbe « Dèyè mòn gen mòn » ?', '["Les difficultés se succèdent", "Les montagnes sont belles", "Il ne faut pas voyager", "Les obstacles sont insurmontables"]', 'Les difficultés se succèdent', 'Derrière les montagnes, il y a d''autres montagnes.'),
('Q0077', 'Dans les contes haïtiens, le personnage de "Bouki" représente souvent :', NULL, 'Que représente Bouki dans les contes haïtiens ?', '["La naïveté", "Le héros triomphant", "La sagesse", "Le chef"]', 'La naïveté', 'Il est toujours trompé par le rusé Ti Malis.'),
('Q0078', 'Le "pwovèb" (proverbe) créole haïtien se caractérise par :', NULL, 'Qu''est-ce qui caractérise un proverbe (pwovèb) créole ?', '["Une formule courte et imagée", "Un long texte", "Un discours politique", "Une chanson"]', 'Une formule courte et imagée', 'Il transmet la sagesse populaire.'),
('Q0079', 'La poésie de Frankétienne en créole se caractérise par :', NULL, 'Qu''est-ce qui caractérise la poésie de Frankétienne ?', '["Le spiralisme", "Le classicisme", "Des rimes régulières", "Un récit sans images"]', 'Le spiralisme', 'Une écriture tourbillonnante et répétitive.'),
('Q0080', 'Le proverbe "Sa ou pa konnen pi gran pase ou" enseigne :', NULL, 'Qu''enseigne le proverbe « Sa ou pa konnen pi gran pase ou » ?', '["L''humilité devant l''inconnu", "Ignorer les autres", "Le savoir est dangereux", "On ne peut rien apprendre"]', 'L''humilité devant l''inconnu', 'Ce qu''on ignore est plus grand que soi.'),
('Q0081', 'Les contes haïtiens ont souvent pour décor :', NULL, 'Quel est le décor habituel des contes haïtiens ?', '["La campagne et la forêt", "Les villes modernes", "La France", "Uniquement des humains"]', 'La campagne et la forêt', 'Avec des animaux qui parlent et des esprits.'),
('Q0082', 'Le terme "kont tradisyonèl" (conte traditionnel) haïtien désigne :', NULL, 'Qu''est-ce qu''un conte traditionnel (kont) haïtien ?', '["Un récit oral transmis", "Un roman moderne", "Un texte religieux", "Un journal intime"]', 'Un récit oral transmis', 'De génération en génération, avec des personnages types et une morale.'),
('Q0083', 'Le proverbe "Bay kou bliye, pote mak sonje" signifie :', NULL, 'Que signifie le proverbe « Bay kou bliye, pote mak sonje » ?', '["Les victimes n''oublient pas", "Il faut oublier le passé", "Les coups sont permis", "La mémoire est inutile"]', 'Les victimes n''oublient pas', 'Celui qui frappe oublie, celui qui porte la cicatrice se souvient.'),
('Q0084', 'Le "teyat" (théâtre) en créole haïtien est notamment représenté par :', NULL, 'Quelles œuvres représentent le théâtre en créole haïtien ?', '["Antigòn et Pèlen tèt", "Des comédies américaines", "Des pièces françaises", "Des sketches télévisés"]', 'Antigòn et Pèlen tèt', 'Antigòn de Morisseau-Leroy ; Pèlen tèt de Frankétienne.'),
('Q0085', 'La figure de "Ti Malice" dans les contes créoles représente :', NULL, 'Que représente Ti Malis dans les contes créoles ?', '["La ruse du faible", "La méchanceté", "La tradition", "L''autorité"]', 'La ruse du faible', 'L''intelligence qui permet au faible de triompher du fort.'),
('Q0086', 'La "chanson peyizan" (chanson paysanne) créole haïtienne exprime :', NULL, 'Qu''exprime la chanson paysanne (chante peyizan) haïtienne ?', '["La vie et les peines rurales", "Des messages politiques seuls", "Des textes catholiques", "La vie urbaine"]', 'La vie et les peines rurales', 'Accompagnée de tambours et de vaksin.'),
('Q0087', 'Un "diksyonè" (dictionnaire) créole-français est utile pour :', NULL, 'À quoi sert un dictionnaire (diksyonè) créole-français ?', '["À connaître sens et orthographe", "À traduire la littérature seule", "À corriger la grammaire seule", "Aux étrangers seulement"]', 'À connaître sens et orthographe', NULL),
