('Q0197', 'Le conditionnel présent s''utilise pour :', NULL, 'Qu''exprime le conditionnel présent dans « Je voudrais un café » ?', '["La politesse", "Le futur certain", "Une habitude", "Un ordre"]', 'La politesse', 'Il exprime aussi l''hypothèse et le futur dans le passé.'),
('Q0199', 'Dans la phrase "Marie lit un roman passionnant", le groupe verbal est :', NULL, 'Dans « Marie lit un roman passionnant », quel est le groupe verbal ?', '["« lit un roman passionnant »", "« Marie lit »", "« un roman passionnant »", "« lit »"]', '« lit un roman passionnant »', 'Le verbe et son complément.'),
('Q0200', 'L''accord de l''adjectif qualificatif se fait en :', NULL, 'Comment s''accorde l''adjectif qualificatif ?', '["En genre et en nombre", "En genre seulement", "En nombre seulement", "Jamais"]', 'En genre et en nombre', 'Avec le nom auquel il se rapporte : une belle fleur, de belles fleurs.'),
('Q0201', 'Un verbe pronominal se conjugue avec :', NULL, 'Avec quoi se conjugue un verbe pronominal ?', '["Un pronom réfléchi", "L''auxiliaire avoir seul", "Aucun pronom", "Un pronom différent du sujet"]', 'Un pronom réfléchi', 'De la même personne que le sujet : je me lave, tu te laves.'),
('Q0202', 'Le subjonctif est requis après :', NULL, 'Après quels verbes le subjonctif est-il requis ?', '["Volonté, doute, émotion", "Les verbes d''état", "Les questions directes", "Les phrases déclaratives"]', 'Volonté, doute, émotion', 'Aussi l''obligation : « Je veux qu''il vienne ».'),
('Q0203', 'La virgule ne s''emploie JAMAIS :', NULL, 'Où ne met-on jamais de virgule ?', '["Entre le sujet et le verbe", "Entre les éléments d''une liste", "Avant « mais »", "Autour d''une apposition"]', 'Entre le sujet et le verbe', 'Sauf pour isoler une incise.'),
('Q0204', 'Un synonyme est un mot :', NULL, 'Qu''est-ce qu''un synonyme ?', '["Un mot de sens proche", "Un mot de sens contraire", "Un mot de même son", "Un mot de même origine"]', 'Un mot de sens proche', 'Exemple : content / heureux.'),
('Q0205', 'Un antonyme est un mot :', NULL, 'Qu''est-ce qu''un antonyme ?', '["Un mot de sens contraire", "Un mot de sens proche", "Un mot qui rime", "Un mot de même radical"]', 'Un mot de sens contraire', 'Exemple : grand / petit.'),
('Q0206', 'La voix passive se forme avec :', NULL, 'Comment forme-t-on la voix passive ?', '["Être + participe passé", "Avoir + participe passé", "Avec « ne… pas »", "Avec un pronom réfléchi"]', 'Être + participe passé', 'Le complément d''objet devient sujet.'),
('Q0207', 'Le futur simple des verbes réguliers se forme avec :', NULL, 'Comment se forme le futur simple des verbes réguliers ?', '["Infinitif + -ai, -as, -a…", "Présent + terminaison", "Imparfait + -rai", "Avoir + participe présent"]', 'Infinitif + -ai, -as, -a…', 'Terminaisons : -ai, -as, -a, -ons, -ez, -ont.'),
('Q0208', 'Un homonyme est un mot :', NULL, 'Qu''est-ce qu''un homonyme ?', '["Un mot de même son", "Un mot de même sens", "Un mot de même orthographe", "Un mot de même langue"]', 'Un mot de même son', 'Exemple : vert, ver, verre, vers.'),
('Q0209', 'La proposition subordonnée relative est introduite par :', NULL, 'Par quoi une proposition subordonnée relative est-elle introduite ?', '["Un pronom relatif", "Une conjonction de subordination", "Un adverbe interrogatif", "Un déterminant démonstratif"]', 'Un pronom relatif', 'Qui, que, dont, où, lequel…'),
('Q0210', 'En français, le genre (masculin/féminin) :', NULL, 'Comment connaît-on le genre d''un nom en français ?', '["Il faut l''apprendre", "Par sa terminaison", "Par son sens", "Par le -e final"]', 'Il faut l''apprendre', 'Il est souvent arbitraire : une table, un bureau.'),
('Q0211', 'La concordance des temps dans une phrase complexe signifie que :', NULL, 'Que signifie la concordance des temps ?', '["L''accord des temps entre propositions", "Tous les verbes au même temps", "Toujours le présent", "Éviter le futur"]', 'L''accord des temps entre propositions', 'Je sais qu''il vient / Je savais qu''il venait.'),
('Q0212', 'Les mots "néanmoins", "cependant", "toutefois" sont des :', NULL, 'Qu''expriment « néanmoins », « cependant », « toutefois » ?', '["L''opposition", "La cause", "Le temps", "L''addition"]', 'L''opposition', 'Ce sont des mots de concession ou d''opposition.'),
('Q0213', 'L''élision (avec apostrophe) se produit quand :', NULL, 'Quand l''élision se produit-elle ?', '["Devant une voyelle", "Entre deux consonnes", "Devant une consonne", "Devant un h aspiré"]', 'Devant une voyelle', 'La voyelle finale tombe : l''arbre, j''aime.'),
('Q0214', 'La liaison obligatoire en français se fait :', NULL, 'Où la liaison est-elle obligatoire en français ?', '["Entre déterminant et nom", "Entre tous les mots", "Jamais à l''oral", "Entre verbe et sujet seuls"]', 'Entre déterminant et nom', 'Devant une voyelle ou un h muet : les enfants.'),
('Q0215', 'Le discours indirect (ou style indirect) transforme les paroles en :', NULL, 'Que devient « Il dit : “Je viens” » au discours indirect ?', '["Il dit qu''il vient", "Il dit : je viens", "Il dit qu''il venait demain", "Il dit que je viens"]', 'Il dit qu''il vient', 'Les personnes et parfois les temps changent.'),
('Q0216', 'Le "ne explétif" en français est :', NULL, 'Qu''est-ce que le « ne » explétif ?', '["Un « ne » non négatif", "La négation normale", "Une faute de grammaire", "Le « ne » sans « pas »"]', 'Un « ne » non négatif', 'Exemple : « Je crains qu''il ne vienne ».'),
('Q0217', 'Une locution verbale est :', NULL, 'Qu''est-ce qu''une locution verbale ?', '["Un groupe verbal figé", "Un verbe de deux syllabes", "Un verbe irrégulier", "Un verbe pronominal"]', 'Un groupe verbal figé', 'Avoir peur, faire semblant, prendre garde.'),
('Q0218', 'Un texte narratif a pour but principal de :', NULL, 'Quel est le but principal d''un texte narratif ?', '["Raconter des événements", "Convaincre", "Décrire", "Expliquer"]', 'Raconter des événements', 'Réels ou fictifs, situés dans le temps et l''espace.'),
('Q0219', 'Un texte argumentatif vise à :', NULL, 'Quel est le but d''un texte argumentatif ?', '["Convaincre en défendant une thèse", "Raconter", "Décrire", "Informer objectivement"]', 'Convaincre en défendant une thèse', 'Avec des arguments et des exemples.'),
('Q0220', 'L''introduction d''un texte argumentatif comprend :', NULL, 'Que comprend l''introduction d''un texte argumentatif ?', '["Accroche, sujet, problématique, plan", "La thèse seule", "Un résumé de la conclusion", "La liste des arguments"]', 'Accroche, sujet, problématique, plan', NULL),
('Q0221', 'Un texte descriptif cherche à :', NULL, 'Que cherche à faire un texte descriptif ?', '["Créer une image précise", "Convaincre", "Raconter", "Expliquer"]', 'Créer une image précise', 'D''un lieu, d''un objet ou d''une personne, à travers les sens.'),
('Q0222', 'Pour reformuler une idée sans la plagier, on peut :', NULL, 'Comment reformuler une idée sans plagier ?', '["Reformuler et citer la source", "Copier entre guillemets", "Traduire en créole", "Supprimer les mots difficiles"]', 'Reformuler et citer la source', 'Avec des synonymes et une autre construction.'),
