('Q0224', 'La lettre de motivation (ou lettre de candidature) doit :', NULL, 'Que doit montrer une lettre de motivation ?', '["Motivation et compétences", "Tous ses diplômes", "Le CV recopié", "Sa disponibilité seule"]', 'Motivation et compétences', 'En lien avec le poste visé, en 3 ou 4 paragraphes.'),
('Q0225', 'Une dissertation philosophique ou littéraire comporte généralement :', NULL, 'Quel plan comporte une dissertation dialectique ?', '["Thèse, antithèse, synthèse", "Une seule partie", "Des exemples seulement", "Un plan chronologique"]', 'Thèse, antithèse, synthèse', NULL),
('Q0226', 'Le registre de langue "soutenu" se caractérise par :', NULL, 'Qu''est-ce qui caractérise le registre de langue soutenu ?', '["Un vocabulaire recherché", "L''argot", "Des phrases très courtes", "L''usage du créole"]', 'Un vocabulaire recherché', 'Des structures complexes, sans familiarités.'),
('Q0227', 'Un compte rendu de lecture doit contenir :', NULL, 'Que contient un compte rendu de lecture ?', '["Résumé, analyse et avis argumenté", "Un résumé seul", "La biographie de l''auteur", "Une traduction"]', 'Résumé, analyse et avis argumenté', 'Il identifie aussi l''œuvre.'),
('Q0228', 'La prise de notes efficace consiste à :', NULL, 'En quoi consiste une prise de notes efficace ?', '["Garder l''essentiel en abrégé", "Tout recopier", "Noter les chiffres seuls", "Enregistrer le discours"]', 'Garder l''essentiel en abrégé', 'Idées principales, abréviations, mise en page claire.'),
('Q0230', 'Un exposé oral réussi doit :', NULL, 'Qu''est-ce qui fait un bon exposé oral ?', '["Une structure claire et des exemples", "Une lecture mot à mot", "Une grande longueur", "Des termes techniques seuls"]', 'Une structure claire et des exemples', 'Avec un début accrocheur et une conclusion marquante.'),
('Q0231', 'La paraphrase se distingue du plagiat car :', NULL, 'Qu''est-ce qui distingue la paraphrase du plagiat ?', '["Elle reformule et cite la source", "Elle change quelques mots", "Elle traduit le texte", "Elle résume sans citer"]', 'Elle reformule et cite la source', NULL),
