('Q0247', 'Le texte argumentatif a pour but de :', NULL, 'Quel est le but d''un texte argumentatif ?', '["Convaincre le lecteur", "Raconter une histoire", "Décrire un paysage", "Expliquer sans prendre parti"]', 'Convaincre le lecteur', NULL),
