('Q0256', 'La "thèse" dans un texte argumentatif est :', NULL, 'Qu''est-ce que la thèse d''un texte argumentatif ?', '["La position défendue", "Un texte philosophique", "L''introduction", "La liste des arguments"]', 'La position défendue', NULL),
('Q0257', 'Les connecteurs logiques de concession en français sont :', NULL, 'Quel connecteur exprime la concession ?', '["Bien que", "Donc", "En outre", "Car"]', 'Bien que', 'Aussi : certes, quoique, même si, malgré.'),
('Q0258', 'Un "paragraphe argumentatif" bien construit (méthode PEEL) contient :', NULL, 'Que contient un paragraphe argumentatif selon la méthode PEEL ?', '["Idée, preuve, explication, lien", "Une idée et un exemple", "Une idée et des définitions", "Des comparaisons"]', 'Idée, preuve, explication, lien', 'Point, Evidence, Explanation, Link.'),
('Q0259', 'La "paraphrase" à éviter dans une analyse littéraire consiste à :', NULL, 'Quel défaut est la paraphrase dans une analyse littéraire ?', '["Redire sans analyser", "Citer trop long", "Ne pas citer", "Trop de figures"]', 'Redire sans analyser', NULL),
