('Q1456', 'L''ADN (acide désoxyribonucléique) est :', NULL, 'Quel est le rôle de l''ADN ?', '["Porter l''information génétique", "Stocker les graisses", "Fournir l''énergie", "Catalyser les réactions"]', 'Porter l''information génétique', 'ADN = acide désoxyribonucléique.'),
('Q1458', 'Un polymère est :', NULL, 'Qu''est-ce qu''un polymère ?', '["Une chaîne de monomères", "Un atome très lourd", "Une molécule à deux atomes", "Un acide aminé isolé"]', 'Une chaîne de monomères', 'C''est une grande molécule formée d''unités répétées.'),
('Q1463', 'Pourquoi les produits chimiques organiques sont-ils nombreux ?', NULL, 'Pourquoi les composés organiques sont-ils si nombreux ?', '["Le carbone forme 4 liaisons", "Ils sont tous naturels", "Le carbone est très lourd", "Le vivant les fabrique tous"]', 'Le carbone forme 4 liaisons', 'Il peut aussi se lier à lui-même en chaînes et en cycles.'),
('Q1464', 'L''amidon est :', NULL, 'Qu''est-ce que l''amidon ?', '["Un polymère de glucose", "Une protéine végétale", "Un acide gras", "Un acide aminé"]', 'Un polymère de glucose', 'C''est la réserve des plantes.'),
('Q1465', 'La cellulose est :', NULL, 'Qu''est-ce que la cellulose ?', '["Un constituant de la paroi végétale", "Une protéine", "Un sucre simple", "Une graisse végétale"]', 'Un constituant de la paroi végétale', 'C''est un polysaccharide ; elle forme les fibres alimentaires.'),
('Q1466', 'Le méthane (CH₄) est important comme :', NULL, 'Pourquoi le méthane (CH₄) est-il important ?', '["Combustible, gaz à effet de serre", "C''est un acide", "Il refroidit", "C''est un engrais"]', 'Combustible, gaz à effet de serre', NULL),
('Q1467', 'Un catalyseur enzymatique (enzyme) est :', NULL, 'Qu''est-ce qu''une enzyme ?', '["Une protéine catalytique", "Un acide fort", "Un sucre complexe", "Une graisse insaturée"]', 'Une protéine catalytique', 'Elle accélère les réactions dans les cellules.'),
('Q1468', 'L''urée (NH₂CONH₂) est un composé organique produit par :', NULL, 'Par quoi l''urée est-elle produite ?', '["Par le corps humain", "Par la photosynthèse", "Par la combustion", "Par la fermentation"]', 'Par le corps humain', 'C''est un déchet de la dégradation des protéines, éliminé dans l''urine.'),
('Q1469', 'Le DDT est un pesticide organochloré qui a été interdit car :', NULL, 'Pourquoi le DDT a-t-il été interdit ?', '["Il s''accumule dans les chaînes alimentaires", "Il ne tue pas les insectes", "Il se dégrade trop vite", "Il coûte trop cher"]', 'Il s''accumule dans les chaînes alimentaires', 'Il est toxique pour la faune.'),
('Q1472', 'Le caoutchouc naturel est un polymère extrait de :', NULL, 'D''où le caoutchouc naturel est-il extrait ?', '["De l''hévéa", "Du pétrole", "De la canne à sucre", "Du maïs"]', 'De l''hévéa', 'Sous forme de latex.'),
