-- Migration 005 : correction du format des questions dont la réponse avait été tronquée
-- Source : corrections hors ligne (2 541 questions), identiques au seed Mobile/lib/services/database_helper.dart
-- Format : vraies questions (pas de « … : »), réponse 1-6 mots, distracteurs de longueur comparable,
--          complément d'explication ajouté à l'explication existante.
-- Correspondance sur l'énoncé actuel (+ titre du chapitre quand l'énoncé existe en double).
-- Idempotent : une ligne déjà corrigée n'est plus retrouvée par son ancien énoncé.

BEGIN;

CREATE TEMP TABLE corr (
    ref TEXT, ancien TEXT, chapitre TEXT, enonce TEXT, choix JSONB, bonne TEXT, complement TEXT
) ON COMMIT DROP;


-- Rapport avant : corrections sans ligne correspondante
SELECT COUNT(*) AS corrections_introuvables
FROM corr c
WHERE NOT EXISTS (
  SELECT 1 FROM questions qq JOIN chapitres ch ON ch.id = qq.chapitre_id
  WHERE qq.enonce = c.ancien AND (c.chapitre IS NULL OR ch.titre = c.chapitre)
);

WITH maj AS (
  UPDATE questions qq
  SET enonce        = c.enonce,
      choix         = c.choix,
      bonne_reponse = c.bonne,
      explication   = CASE WHEN c.complement IS NULL THEN qq.explication
                           ELSE btrim(coalesce(qq.explication, '') || ' ' || c.complement) END
  FROM corr c, chapitres ch
  WHERE ch.id = qq.chapitre_id
    AND qq.enonce = c.ancien
    AND (c.chapitre IS NULL OR ch.titre = c.chapitre)
  RETURNING qq.id
)
SELECT COUNT(*) AS questions_corrigees FROM maj;

-- Contrôle : plus aucun énoncé terminé par « : » parmi les questions corrigées
SELECT COUNT(*) AS enonces_a_completer_restants
FROM questions qq JOIN corr c ON qq.enonce = c.enonce
WHERE rtrim(qq.enonce) LIKE '%:';

COMMIT;
